/**
 * Regenerates src/data/portfolio.ts from the live GitHub account.
 *
 * The generated file is committed, so a normal build never touches the network.
 * Re-run this when the repositories change:
 *   npm run sync:github
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const USERNAME = 'unknownparticles';
const here = dirname(fileURLToPath(import.meta.url));
const output = join(here, '..', 'src', 'data', 'portfolio.ts');

function hasGh() {
  try {
    execFileSync('gh', ['--version'], { stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
}

async function fetchJson(path) {
  if (hasGh()) {
    const raw = execFileSync('gh', ['api', path, '--paginate'], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
    try {
      return JSON.parse(raw);
    } catch {
      // --paginate concatenates arrays; fall through to the plain request.
      const single = execFileSync('gh', ['api', path], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
      return JSON.parse(single);
    }
  }

  const url = `https://api.github.com${path}`;
  const headers = { Accept: 'application/vnd.github+json', 'User-Agent': 'alun-dev-notes-sync' };
  const token = process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
  if (token) headers.Authorization = `Bearer ${token}`;

  for (let attempt = 1; attempt <= 4; attempt += 1) {
    const response = await fetch(url, { headers });
    if (response.ok) return response.json();
    if (response.status === 403 || response.status === 429) {
      process.stderr.write(`rate limited, retrying (${attempt}/4)\n`);
      await new Promise((resolve) => setTimeout(resolve, 15_000));
      continue;
    }
    throw new Error(`${url} -> ${response.status}`);
  }
  throw new Error(`${url} -> giving up after retries`);
}

const profile = await fetchJson(`/users/${USERNAME}`);
const repos = await fetchJson(`/users/${USERNAME}/repos?per_page=100&sort=pushed&direction=desc`);

const own = repos.filter((repo) => !repo.fork && !repo.archived);
const withPages = own.filter((repo) => repo.has_pages);
const described = own.filter((repo) => repo.description && repo.description.trim());

const demoUrl = (repo) => `https://${USERNAME}.github.io/${repo.name}/`;
const repoUrl = (repo) => repo.html_url;

const featured = [...own]
  .sort((a, b) => b.stargazers_count - a.stargazers_count || b.pushed_at.localeCompare(a.pushed_at))
  .slice(0, 5)
  .map((repo) => ({
    name: repo.name,
    summary: repo.description?.trim() || '尚未填写描述。',
    language: repo.language || 'Other',
    stars: repo.stargazers_count,
    repoUrl: repoUrl(repo),
    ...(repo.has_pages ? { demoUrl: demoUrl(repo) } : {}),
  }));

const live = withPages
  .filter((repo) => repo.description && repo.description.trim())
  .slice(0, 8)
  .map((repo) => ({
    name: repo.name,
    title: repo.description.trim(),
    summary: `${repo.language || 'Other'} · 最近更新于 ${repo.pushed_at.slice(0, 10)}`,
    repoUrl: repoUrl(repo),
    demoUrl: demoUrl(repo),
  }));

const languageCounts = own.reduce((counts, repo) => {
  const key = repo.language || 'Other';
  counts[key] = (counts[key] ?? 0) + 1;
  return counts;
}, {});

const languages = Object.entries(languageCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([language, count]) => ({ language, count }));

const verifiedAt = new Date().toISOString().slice(0, 10);

const body = `// Generated by scripts/sync-github.mjs on ${verifiedAt}. Do not edit by hand.
// Source: the public GitHub API for @${USERNAME}.

export type LanguageCount = { language: string; count: number };
export type FeaturedProject = {
  name: string;
  summary: string;
  language: string;
  stars: number;
  repoUrl: string;
  demoUrl?: string;
};
export type LiveDemo = {
  name: string;
  title: string;
  summary: string;
  repoUrl: string;
  demoUrl: string;
};

const languages: LanguageCount[] = ${JSON.stringify(languages, null, 2)};

export const portfolio = {
  profileName: ${JSON.stringify(profile.name ?? USERNAME)},
  username: ${JSON.stringify(profile.login)},
  bio: ${JSON.stringify(profile.bio ?? '')},
  avatarUrl: ${JSON.stringify(profile.avatar_url)},
  githubUrl: ${JSON.stringify(profile.html_url)},
  repositoriesUrl: 'https://github.com/${USERNAME}?tab=repositories',
  ownRepositoryCount: ${own.length},
  pagesRepositoryCount: ${withPages.length},
  describedRepositoryCount: ${described.length},
  followerCount: ${profile.followers},
  verifiedAt: ${JSON.stringify(verifiedAt)},
  languages,
  featuredProjects: ${JSON.stringify(featured, null, 2)} as FeaturedProject[],
  liveDemos: ${JSON.stringify(live, null, 2)} as LiveDemo[],
};
`;

writeFileSync(output, body, 'utf8');

console.log(`wrote ${output}`);
console.log(`  own repositories      ${own.length}`);
console.log(`  with GitHub Pages     ${withPages.length}`);
console.log(`  with a description    ${described.length}`);
console.log(`  featured              ${featured.length}`);
console.log(`  live demos listed     ${live.length}`);
